"""
Mock OAuth Provider — 模拟 Google OAuth2 userinfo 端点

监听 127.0.0.1:9090，提供端点：
  GET /oauth/userinfo — 根据 Authorization: Bearer <token> 返回用户信息

Token 格式：mock_<email>_<name>
例如：mock_alice@example.com_Alice
返回：{"sub": "google-<hash>", "email": "alice@example.com", "name": "Alice", "email_verified": true}

无效 token → 401

用法：python mock_oauth_server.py [port]

在 start.sh 中启动：
    python /app/lib/mock_oauth_server.py &
"""

import hashlib
import json
import sys
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs


class OAuthHandler(BaseHTTPRequestHandler):

    def do_GET(self):
        parsed = urlparse(self.path)

        if parsed.path == "/oauth/userinfo":
            self._handle_userinfo()
        elif parsed.path == "/health":
            self.send_response(200)
            self.end_headers()
            self.wfile.write(b"ok")
        else:
            self.send_response(404)
            self.end_headers()

    def do_POST(self):
        parsed = urlparse(self.path)

        if parsed.path == "/oauth/token":
            self._handle_token_exchange()
        else:
            self.send_response(404)
            self.end_headers()

    def _handle_userinfo(self):
        auth = self.headers.get("Authorization", "")
        if not auth.startswith("Bearer "):
            self._error(401, "missing or invalid authorization header")
            return

        token = auth[len("Bearer "):]
        user_info = self._parse_token(token)
        if user_info is None:
            self._error(401, "invalid_token")
            return
